// src/content/items/sunsword.js
// ──────────────────────────────────────────────────────────────────
// Sunsword — content DSL port.
//
// The original sunsword was spread across 7+ files:
//   itemCatalogEquipment.js (catalog + on_use hook)
//   itemAbilityConstants.js (cooldown constant)
//   scrollWandWiring.js (ray handler + targeting + blind logic)
//   hudFeeds.js (hardcoded spell bar icon)
//   boltFxController.js (line VFX)
//   lighting/sources/index.js (holy beam lighting)
//   floatTextWiring.js (BLINDED! float text + particles)
//
// Now: this one file.
// ──────────────────────────────────────────────────────────────────

import { defineItem } from '../define.js';

defineItem('sunsword', {
  name:        'Sunsword',
  type:        'weapon',
  glyph:       '/',
  color:       '#ffffff',
  glow:        '#ffe8a0',
  scale:       0.8,
  weight:      1.6,
  value:       280,
  rarity:      'epic',
  material:    'gold',
  description: 'A blade of living light, warm to the touch. Undead recoil at its radiance.',
  tags:        ['sunlight'],

  // ── Equipment stats ───────────────────────────────────────────
  bonuses:     { attack: 2, damagePower: 2 },
  damageDice:  '1d8',
  damageType:  'slash',
  staminaCost: 8,

  swingProfile: {
    lengthCm:    116,
    length:      1.18,
    widthScale:  0.96,
    handleStart: 0.22,
    alphaStops: [
      [0.00, 0.22],
      [0.45, 0.60],
      [0.86, 0.95],
      [1.00, 1.00],
    ],
  },

  // ── Abilities ─────────────────────────────────────────────────
  // Declared here, shows up in the spell bar automatically.
  // Targeting, cooldown, and activation — all in one place.
  abilities: {
    blinding_ray: {
      name:        'Blinding Ray',
      icon:        '☼',
      targeting:   'enemy',
      range:       6,
      cooldown:    12,
      description: 'A searing ray of sunlight that blinds the target.',
      displayFormat: '{description} Range: {range} tiles. Cooldown: {cooldown} turns.',

      onActivate(ctx) {
        // Apply blind to the targeted enemy
        ctx.apply(ctx.target, 'blinded', 5);

        // Cooldown
        ctx.setCooldown(12);

        // Message
        ctx.message('A searing ray of light strikes {target} — it is blinded!');

        // Presentation: beam from user to target + flash
        ctx.present('blinding_ray', {
          target: ctx.target,
          user:   ctx.user,
        });
      },
    },
  },

  // ── Presentations ─────────────────────────────────────────────
  presentations: {
    blinding_ray: {
      sound: 'holy_beam',
      vfx: [
        { type: 'beam',      color: '#ffffa0' },
        { type: 'flash',     color: '#fffbe6', radius: 2 },
        { type: 'floatText', text: 'BLINDED!', color: '#ffffa0', life: 1.4 },
      ],
    },
  },
});

    targeting.openEnemyTargeting({
      spellId: '__scroll_taming__',
      spellName: 'Scroll of Taming',
      range: 8,
      enemies,
      onConfirm: (enemyId) => {
        world.emit?.('scroll:taming:apply', { actor, target: enemyId });
      },
    });
  });

  // ── Scroll of Identify (Use verb with no apply target selected) ────────
  world.on('scroll:identify', ({ actor, scrollId }) => {
    const targets = listApplyTargetsForTool(world, actor, scrollId);
    if (targets.length === 0) {
      world.emit?.('message', { text: 'You have nothing that needs identifying.', type: 'system' });
      return;
    }
    window.dispatchEvent(new CustomEvent('ui:openApplyForTool', { detail: { toolId: scrollId } }));
  });

  // ── Wand of Stasis ──────────────────────────────────────────────────────
  world.on('wand:stasis', ({ actor }) => {
    const pe = playerEntity();
    if (!pe) return;
    const range = 6;
    const enemies = scanVisibleEnemies(world, pe.pos.x | 0, pe.pos.y | 0, range, { playerId: pe.id });
    if (enemies.length === 0) {
      world.emit?.('message', { text: 'No visible enemies to freeze.', type: 'system' });
      return;
    }

    targeting.openEnemyTargeting({
      spellId: '__wand_stasis__',
      spellName: 'Wand of Stasis',
      range,
      enemies,
      onConfirm: (enemyId) => {
        if (!applyWandStasis(world, enemyId)) return;
        const ni = world.get(enemyId, NamedIdentity);
        const name = ni?.name || 'creature';
        world.emit?.('message', { text: `The ${name} is frozen outside of time!`, type: 'system' });
        const pos = world.get(enemyId, Position);
        if (pos) world.emit?.('wand:stasis:vfx', { id: enemyId, x: pos.x | 0, y: pos.y | 0 });
      },
    });
  });

  // Sunsword Blinding Ray: migrated to content DSL (src/content/items/sunsword.js)

  // ── Scroll of Aggravation ───────────────────────────────────────────────
  world.on('scroll:aggravation', ({ actor }) => {
    const pe = playerEntity();
    if (!pe) return;
    const px = pe.pos.x | 0;
    const py = pe.pos.y | 0;
    for (const [eid, aggro, fac] of world.query(AggroState, Faction)) {
      if (fac.key !== 'enemy') continue;
      const vit = world.get(eid, Vitality);
      if (!vit || (vit.hp | 0) <= 0) continue;
      aggro.alertLevel = AGGRO_LEVELS.hunting;
      aggro.lastKnownX = px;
      aggro.lastKnownY = py;
      aggro.searchTurnsLeft = SEARCH_TURNS_HUNTING_GRACE;
    }
  });

  // ── Scroll of Teleportation ─────────────────────────────────────────────
  world.on('scroll:teleportation', ({ actor }) => {
    const pos = world.get(actor, Position);
    if (!pos) return;
    const from = { x: pos.x | 0, y: pos.y | 0 };
    const candidates = [];
    forEachLoadedTile((x, y) => {
      if (!isWalkable(x, y)) return;
      const dist = chebyshevScalar(x, y, from.x, from.y);
      if (dist < 6) return;
      candidates.push({ x, y });
    });
    if (candidates.length === 0) {
      world.emit?.('message', { text: 'The scroll fizzles.', type: 'system' });
      return;
    }
    const to = candidates[Math.floor(world.rand() * candidates.length)];
    world.set(actor, Position, { x: to.x, y: to.y });
    world.emit('moved', { id: actor, from, to });
    world.emit('teleported', { id: actor, from, to, source: 'scroll:teleportation' });
  });

  // ── Scroll of Summoning ─────────────────────────────────────────────────

