    const identity = world.get(itemId, NamedIdentity)?.identity || '';
    const def = getCatalogItem(identity);
    const abilityId = requestedAbilityId || (def?._contentDefaultAbility ? Object.keys(def._contentAbilities || {})[0] : '');
